export type ApiErrorCode = (typeof API_ERROR_CODES)[number];

/** Codes that come as a prefix plus a word (for example indiamart_<word>): map the whole family with one sentence. */
export const API_ERROR_CODE_FAMILIES = [
  "indiamart_",
  "recording_",
] as const;

export function isKnownApiErrorCode(code: string): code is ApiErrorCode {
  return (API_ERROR_CODES as readonly string[]).includes(code);
}
